import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"周易尚氏学 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"周易尚氏学 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/009.md","filePath":"zh/classics/shangshi/009.md"}'),h={name:"zh/classics/shangshi/009.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>艮少。坎隐伏不明。故名曰蒙。蒙樨也。不明也。二得中有应故亨。艮为童蒙。为求。而二至上正反艮。自二言若求五。自五言若求二。有互相求之象。然二阳也。阳大明。五阴也阴迷。我谓二。匪我求童蒙。童蒙求我者。言二不必求五。五自来应二也。传曰志应。言二五相应与相上下也。旧解诂实匪字。定谓二不应五者非也。坎为圣为通故为筮。比曰原筮。亦以坎为筮。震为言。放曰告。而二至上正反震。言多。故曰渎。渎亵渎也。震反为艮。艮止故不告。昔贤说此。总不知再三渎之故何在。由正覆象并用之义。失传故也。又筮象亦失传。故初筮不知何所指。岂知坎在下故曰初筮。专指九二。艮坎皆冬日卦。故曰利贞。</p><p>彖曰。蒙。山下有险。险而止。蒙。蒙亨。以亨行。时中也。匪我求童蒙。童蒙求我。志应也。初筮告。以刚中也。再三渎。渎则不告。渎蒙也。蒙以养正。圣功也。</p><p>志应。言二五互求也。坎为圣。故曰圣功。</p><p>象曰。山下出泉。蒙。君子以果行育德。</p><p>艮为君子。为坚。为果。震为行。故曰果行。果行者。言坚定不易也。传曰。致果为毅。是其义也。震为生为德。故曰育德。以者。法也。言君子法蒙象。而果毅其行。养育其德也。</p><p>初六。发蒙。利用刑人。用说桎梏。以往吝。</p><p>发启也。诗大雅。思齐篇曰。刑于寡妻。左传襄十三年。一人刑善。数世赖之。注皆训刑为法。是刑与型同。利用刑人者。言宜树之模型。使童蒙有所法式。得为成人。永免罪辟也。坎为桎梏。说文。桎足械。梏手械。四无应。故往吝。说文引作遴。云行难也。吝遴古通。汉书鲁安王传。晚节遴。王莽传。性实遴啬。义皆为吝。以往。王安石。朱震。王宗传。朱子。皆训为以后。大误。</p><h3 id="象曰。利用刑人。以正法也。" tabindex="-1">象曰。利用刑人。以正法也。 <a class="header-anchor" href="#象曰。利用刑人。以正法也。" aria-label="Permalink to “象曰。利用刑人。以正法也。”">​</a></h3><p>正平也。坎为平。故曰正法。言以法则示人。俾童蒙有所则效。即释刑人之义也。</p><p>九二。苞蒙。吉。纳妇。吉。子克家。</p><p>阳居阴中。故曰苞蒙。五阴来应。故曰纳妇吉。震为子。艮为家。五艮体。二应之。故曰子克家。克者能也。言能任家事也。</p><h3 id="象曰。子克家。刚柔接也。" tabindex="-1">象曰。子克家。刚柔接也。 <a class="header-anchor" href="#象曰。子克家。刚柔接也。" aria-label="Permalink to “象曰。子克家。刚柔接也。”">​</a></h3><p>接与龙战于野战字义同。言交接也。</p><p>六三。勿用取女。见金夫。不有躬。无攸利。</p><p>取娶同。坤为女。见金夫。不用躬。申勿用之故也。金夫者美称。诗有匪君子。如金如锡。如圭如璧。左传。思我王度。式如玉。式如金。皆以金喻人之美。艮为金。为夫。人徒知乾为金。不知艮坚亦为金。易林随之屯云。金玉满堂。以屯之互艮为金也。人徒知震有夫象。不知三男皆为夫。比曰后夫凶。以艮为夫也。易林复之剥云。夫亡从军。以剥上艮为夫也。三与上艮应。故曰见金夫。坤为躬。三体震。震为行而决躁。故见金夫而亟欲往上。不顾四五之阻。故曰不有躬。女行如此。不顺。故无所利也。</p><h3 id="象曰。勿用取女。行不顺也。" tabindex="-1">象曰。勿用取女。行不顺也。 <a class="header-anchor" href="#象曰。勿用取女。行不顺也。" aria-label="Permalink to “象曰。勿用取女。行不顺也。”">​</a></h3><p>坤为顺。震躁动。故不顺。案此爻旧解。虞翻以阳为金。谓三为二所淫。朱子谓金夫。盖以金赂己而挑之。若鲁秋胡之事。均堪喷饭。若夫王弼以金夫为刚夫。毛大可惠栋等用卦变。又以兑阳为金。皆非。故夫卦象一失传。无论若何揣测。皆不能当。其关系之重若是。</p><p>六四。困蒙。吝。</p><p>四无应。承乘皆失类。故曰困。</p><h3 id="象曰。困蒙之吝。独远实也。" tabindex="-1">象曰。困蒙之吝。独远实也。 <a class="header-anchor" href="#象曰。困蒙之吝。独远实也。" aria-label="Permalink to “象曰。困蒙之吝。独远实也。”">​</a></h3><p>实为阳。初三五皆近阳。四独否。故曰独远实。</p><p>六五。童蒙吉。</p><p>艮为童蒙。上承阳。下应二。虽不当位。而居中。故吉。</p><h3 id="象曰。童蒙之吉。顺以巽也。" tabindex="-1">象曰。童蒙之吉。顺以巽也。 <a class="header-anchor" href="#象曰。童蒙之吉。顺以巽也。" aria-label="Permalink to “象曰。童蒙之吉。顺以巽也。”">​</a></h3><p>上承阳。顺阳而行。下与二相上下。故曰顺以巽。</p><p>上九。击蒙。不利为寇。利御寇。</p><p>艮手为击。亦启发之意。上应在三。三坎为寇。道穷于上。故不利为寇。然艮为坚为守。下拥群阴。势众。故利御寇。坎彖传云。王公设险以守其国。守谓互艮也。能守故利。</p><h3 id="象曰。利用御寇。上下顺也。" tabindex="-1">象曰。利用御寇。上下顺也。 <a class="header-anchor" href="#象曰。利用御寇。上下顺也。" aria-label="Permalink to “象曰。利用御寇。上下顺也。”">​</a></h3><p>君子守其前。小人随其后。故利御寇。上下顺者。言坤民顺上也。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
